style.css:
@-moz-document domain("discord.com"), domain("discordapp.com") {
:root {
    --neon-scrollbar: linear-gradient(45deg, #711c91 0%, #ea00d9 42%, #0abdc6 85%, #72f5ff 100%);
    --neon-font: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace;
    --neon-panel-opacity: 0.47;
    --neon-panel: rgba(9, 24, 51, var(--neon-panel-opacity));
    --neon-popup: rgba(9, 24, 51, 0.97);
    --neon-text: #e2f6ff;
    --neon-muted: #a4bfdc;
    --neon-border: rgba(10, 189, 198, 0.36);
    --neon-hover: rgba(19, 62, 124, 0.47);
    --neon-selected: rgba(113, 28, 145, 0.61);
  }

  /* Keep the Cyberpunk Neon palette in either Discord appearance mode. */
  .theme-dark, .theme-light {
    --neon-panel: rgba(9, 24, 51, var(--neon-panel-opacity));
    --neon-popup: rgba(9, 24, 51, 0.97);
    --neon-text: #e2f6ff;
    --neon-muted: #a4bfdc;
    --neon-border: rgba(10, 189, 198, 0.36);
    --neon-hover: rgba(19, 62, 124, 0.47);
    --neon-selected: rgba(113, 28, 145, 0.61);
    --font-primary: var(--neon-font) !important;
    --font-display: var(--neon-font) !important;
    --font-code: var(--neon-font) !important;
    --text-default: #e2f6ff !important;
    --text-link: #72f5ff !important;
    --text-brand: #38e7ee !important;
    --brand-500: #f34ae7 !important;
    --brand-560: #ca00ba !important;
    --brand-600: #aa009d !important;
    --brand-experiment: #f34ae7 !important;
    --button-filled-brand-text: #000b1e !important;
    --button-filled-brand-background: #f34ae7 !important;
    --button-filled-brand-background-hover: #ff83f3 !important;
    color-scheme: dark !important;
  }

  .theme-dark, .theme-light {
    --background-base-lowest: transparent !important;
    --background-base-lower: transparent !important;
    --background-base-low: transparent !important;
    --background-primary: transparent !important;
    --background-secondary: transparent !important;
    --background-secondary-alt: transparent !important;
    --background-tertiary: transparent !important;
    --bg-base-primary: transparent !important;
    --bg-base-secondary: transparent !important;
    --bg-base-tertiary: transparent !important;
    --background-surface-high: var(--neon-panel) !important;
    --background-surface-higher: var(--neon-popup) !important;
    --background-surface-highest: var(--neon-popup) !important;
    --background-floating: var(--neon-popup) !important;
    --background-modifier-hover: var(--neon-hover) !important;
    --background-modifier-active: var(--neon-selected) !important;
    --background-modifier-selected: var(--neon-selected) !important;
    --background-modifier-accent: var(--neon-border) !important;
    --channeltextarea-background: var(--neon-panel) !important;
    --chat-background-default: transparent !important;
    --chat-background: transparent !important;
    --text-normal: var(--neon-text) !important;
    --text-primary: var(--neon-text) !important;
    --text-secondary: var(--neon-muted) !important;
    --text-muted: var(--neon-muted) !important;
    --header-primary: var(--neon-text) !important;
    --header-secondary: var(--neon-muted) !important;
    --channels-default: var(--neon-muted) !important;
    --interactive-normal: var(--neon-muted) !important;
    --interactive-hover: var(--neon-text) !important;
    --interactive-active: var(--neon-text) !important;
    --input-background: var(--neon-panel) !important;
    --border-subtle: var(--neon-border) !important;
    --border-normal: var(--neon-border) !important;
  }

  /* Repeating cyan and magenta honeycomb with CRT scanlines. */
  html {
    min-height: 100%;
    background-color: #0a0a0a !important;
    background-image:
      repeating-linear-gradient(0deg,
        rgba(0, 245, 255, .045) 0px,
        rgba(0, 245, 255, .045) 1px,
        transparent 1px, transparent 4px),
      url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2272%22%20height%3D%2241.57%22%20viewBox%3D%220%200%2072%2041.57%22%20fill%3D%22none%22%20stroke-width%3D%221%22%3E%3Cpath%20d%3D%22M0%2020.785L12%200H36L48%2020.785M0%2020.785L12%2041.57H36L48%2020.785%22%20stroke%3D%22%230abdc6%22%20stroke-opacity%3D%22.36%22%2F%3E%3Cpath%20d%3D%22M48%2020.785H72%22%20stroke%3D%22%23ea00d9%22%20stroke-opacity%3D%22.44%22%2F%3E%3C%2Fsvg%3E") !important;
    background-size: auto, 72px 41.57px !important;
    background-position: 0 0 !important;
    background-repeat: repeat !important;
    background-attachment: fixed !important;
  }
  body {
    min-height: 100vh;
    background: transparent !important;
  }
  #app-mount,
  #app-mount > [class*="app_"],
  #app-mount [class*="appAsidePanelWrapper_"],
  #app-mount [class*="base_"],
  #app-mount [class*="bg_"],
  #app-mount [class*="sidebar_"],
  #app-mount [class*="sidebarList_"],
  #app-mount [class*="chatContent_"],
  #app-mount [class*="messagesWrapper_"],
  #app-mount [class*="membersWrap_"],
  #app-mount [class*="scrollerBase_"] {
    background: transparent !important;
  }

  /* Major columns receive their own translucent surface. Nested scrolling
     wrappers remain clear so repeated glass layers do not hide the gradient. */
  #app-mount [class*="guilds_"],
  #app-mount [class*="sidebarList_"] > [class*="container_"],
  #app-mount [class*="privateChannels_"],
  #app-mount [class*="chat_"],
  #app-mount [class*="members_"],
  #app-mount [class*="container_"][class*="themed_"] {
    background: var(--neon-panel) !important;
    border-color: var(--neon-border) !important;
  }
  #app-mount [class*="guilds_"] [class*="scroller_"],
  #app-mount [class*="sidebarList_"] [class*="scroller_"],
  #app-mount [class*="privateChannels_"] [class*="scroller_"],
  #app-mount [class*="members_"] > div,
  #app-mount [class*="member_"],
  #app-mount [class*="chat_"] [class*="content_"] {
    background-color: transparent !important;
  }

  /* Account controls and composer. */
  #app-mount [class*="panels_"],
  #app-mount [class*="channelTextArea_"],
  #app-mount [class*="searchBar_"] {
    background: var(--neon-panel) !important;
    border: 1px solid var(--neon-border) !important;
  }
  #app-mount [class*="channelTextArea_"] [class*="scrollableContainer_"],
  #app-mount [class*="form_"],
  #app-mount [class*="typing_"] {
    background: transparent !important;
  }
  #app-mount [class*="form_"]::before,
  #app-mount [class*="form_"]::after,
  #app-mount [class*="sidebar_"]::after {
    background: none !important;
  }

  /* Floating surfaces stay darker for readable menus over the grid background. */
  #app-mount [role="menu"],
  #app-mount [role="listbox"],
  #app-mount [role="dialog"],
  #app-mount [class*="tooltip_"],
  #app-mount [class*="messagesPopoutWrap_"],
  #app-mount [class*="recentMentionsPopout_"],
  #app-mount [class*="userProfileOuter_"],
  #app-mount [class*="emojiPicker_"],
  #app-mount [class*="expressionPickerPositionLayer_"],
  #app-mount [class*="autocomplete_"],
  #app-mount [class*="searchResultsWrap_"] {
    background: var(--neon-popup) !important;
    color: var(--neon-text) !important;
    border: 1px solid var(--neon-border) !important;
    box-shadow: 0 10px 32px rgba(0, 0, 0, 0.3) !important;
  }
  #app-mount [class*="standardSidebarView_"] {
    background: var(--neon-popup) !important;
  }
  #app-mount [class*="sidebarRegionScroller_"],
  #app-mount [class*="contentRegion_"],
  #app-mount [class*="contentRegionScroller_"] {
    background: transparent !important;
  }

  /* Subtle selections preserve avatars, attachments and status colors. */
  #app-mount [class*="member_"]:hover,
  #app-mount [class*="interactive_"]:hover,
  #app-mount [class*="message_"]:hover {
    background-color: var(--neon-hover) !important;
  }
  #app-mount [class*="messageContent_"] {
    color: var(--neon-text) !important;
  }
  #app-mount [class*="messageContent_"] pre,
  #app-mount [class*="messageContent_"] code {
    background: var(--neon-panel) !important;
    border-color: var(--neon-border) !important;
  }
  #app-mount a:focus-visible,
  #app-mount button:focus-visible,
  #app-mount [tabindex="0"]:focus-visible {
    outline: 2px solid #38e7ee !important;
    outline-offset: 2px;
  }
  #app-mount [class*="homeIcon_"] {
    color: #38e7ee !important;
    filter: drop-shadow(0 0 4px #38e7ee) drop-shadow(0 0 8px rgba(234,0,217,.65));
  }
  #app-mount * {
    /* Chromium must use auto here so native scrollbar colors do not
       override the gradient pseudo-elements below. */
    scrollbar-width: auto !important;
    scrollbar-color: auto !important;
  }
  #app-mount ::-webkit-scrollbar {
    width: 10px !important;
    height: 10px !important;
  }
  #app-mount ::-webkit-scrollbar-track {
    background: rgba(0, 0, 0, 0.15) !important;
  }
  #app-mount ::-webkit-scrollbar-thumb {
    background: var(--neon-scrollbar) !important;
    border: 2px solid transparent !important;
    background-clip: padding-box !important;
    border-radius: 10px !important;
    min-height: 32px;
    min-width: 32px;
  }

  /* Friends list: match the left sidebar's translucent panel.
     data-list-id is taken from the supplied Friends list markup. */
  #app-mount [data-list-id="people"][class*="peopleList_"] {
    background: var(--neon-panel) !important;
    box-shadow: inset 0 0 0 1px var(--neon-border) !important;
  }

  /* Friends side panel: outer container from the supplied markup.
     One tinted surface covers both its header and its scrolling list. */
  #app-mount .container_b17982 {
    background: var(--neon-panel) !important;
    box-shadow: inset 0 0 0 1px var(--neon-border) !important;
  }
  #app-mount .container_b17982 > .body_b17982,
  #app-mount .container_b17982 > .header_b5f5a6,
  #app-mount .container_b17982 [data-list-id="friends-list"],
  #app-mount .container_b17982 [data-list-id="friends-list"] > [role="list"] {
    background: transparent !important;
  }
  #app-mount ::-webkit-scrollbar-thumb:hover {
    box-shadow: inset 0 0 0 20px rgba(114, 245, 255, 0.15) !important;
  }
  #app-mount ::-webkit-scrollbar-corner {
    background: transparent !important;
  }

  /* Terminal typography via Discord tokens and native form controls. */
  html, body, #app-mount,
  #app-mount button, #app-mount input, #app-mount textarea,
  #app-mount select, #app-mount [contenteditable="true"] {
    font-family: var(--neon-font) !important;
    font-variant-ligatures: none !important;
  }
  #app-mount { color: var(--neon-text) !important; }
  #app-mount ::selection {
    background: rgba(234,0,217,.35) !important;
    color: #fff4ff !important;
  }
  #app-mount [class*="guilds_"],
  #app-mount [class*="sidebarList_"] > [class*="container_"],
  #app-mount [class*="privateChannels_"],
  #app-mount [class*="chat_"],
  #app-mount [class*="members_"] {
    box-shadow: inset 0 0 0 1px rgba(10,189,198,.18) !important;
  }
  #app-mount [class*="actionButton_"],
  #app-mount [class*="modeSelectButton_"],
  #app-mount [class*="reaction_"] {
    background-color: rgba(19, 62, 124, 0.88) !important;
    color: #e2f6ff !important;
    border-color: var(--neon-border) !important;
  }

  /* Matching midnight-blue glass for the side columns. */
#app-mount [class*="guilds_"],
  #app-mount [class*="sidebarList_"],
  #app-mount [class*="privateChannels_"],
  #app-mount [class*="members_"],
  #app-mount .container_b17982 {
    --neon-text: #38e7ee !important;
    --neon-muted: #a0e7f2 !important;
    --text-default: #38e7ee !important;
    --text-normal: #38e7ee !important;
    --text-primary: #38e7ee !important;
    --text-secondary: #a0e7f2 !important;
    --text-muted: #a0e7f2 !important;
    --header-primary: #a0e7f2 !important;
    --header-secondary: #a0e7f2 !important;
    --channels-default: #38e7ee !important;
    --interactive-normal: #38e7ee !important;
    --interactive-hover: #fff0ff !important;
    --interactive-active: #fff0ff !important;
    --background-modifier-hover: rgba(19, 62, 124, 0.42) !important;
    --background-modifier-selected: rgba(113, 28, 145, 0.52) !important;
    color: #38e7ee !important;
  }
  #app-mount [class*="guilds_"],
  #app-mount [class*="sidebarList_"] > [class*="container_"],
  #app-mount [class*="privateChannels_"],
  #app-mount [class*="members_"],
  #app-mount .container_b17982 {
    background: rgba(9, 24, 51, 0.75) !important;
    box-shadow: inset 0 0 0 1px rgba(10,189,198,.24) !important;
  }
  #app-mount [class*="sidebarList_"] [class*="name_"],
  #app-mount [class*="sidebarList_"] [class*="username_"],
  #app-mount [class*="sidebarList_"] [class*="channelName_"],
  #app-mount [class*="privateChannels_"] [class*="name_"],
  #app-mount [class*="privateChannels_"] [class*="username_"],
  #app-mount [class*="privateChannels_"] [class*="channelName_"],
  #app-mount [class*="members_"] [class*="name_"],
  #app-mount [class*="members_"] [class*="username_"],
  #app-mount [class*="members_"] [class*="channelName_"],
  #app-mount .container_b17982 [class*="name_"],
  #app-mount .container_b17982 [class*="username_"],
  #app-mount .container_b17982 [class*="channelName_"] {
    color: #38e7ee !important;
  }
  #app-mount [class*="membersGroup_"],
  #app-mount .container_b17982 .header_b5f5a6,
  #app-mount .container_b17982 [class*="header__1af21"] {
    color: #a0e7f2 !important;
  }
  /* Active navigation gets a magenta edge without changing its size. */
  #app-mount [class*="modeSelected_"] [class*="link_"],
  #app-mount [class*="privateChannels_"] [aria-current="page"] {
    background-color: var(--neon-selected) !important;
    box-shadow: inset 2px 0 0 #ea00d9 !important;
  }
  /* Corner blooms sit over the honeycomb on the page background. */
  #app-mount {
    background:
      radial-gradient(ellipse 38vw 34vh at top left, rgba(0, 245, 255, .90), rgba(0, 213, 255, .45) 34%, transparent 100%),
      radial-gradient(ellipse 38vw 34vh at top right, rgba(255, 0, 221, .90), rgba(234, 0, 217, .45) 34%, transparent 100%),
      radial-gradient(ellipse 38vw 34vh at bottom left, rgba(255, 0, 221, .90), rgba(234, 0, 217, .45) 34%, transparent 100%),
      radial-gradient(ellipse 38vw 34vh at bottom right, rgba(0, 245, 255, .90), rgba(0, 213, 255, .45) 34%, transparent 100%) !important;
  }
}
